async () => {
  await new Promise(r => setTimeout(r, 12000));
  // 收集可能的 toast / 提示文本
  const candidates = [];
  document.querySelectorAll('div, span, p').forEach(el => {
    const t = (el.innerText || '').trim();
    if (t && t.length < 120 && /PDF|导出|下载|编译|成功|失败|任务/.test(t)) {
      const rect = el.getBoundingClientRect();
      if (rect.width > 0) candidates.push(t);
    }
  });
  return { texts: [...new Set(candidates)].slice(0, 30) };
}

